const { proxy, revoke } = Proxy.revocable(session, {
  get: (t, p, r) => {
    const v = Reflect.get(t, p, r);
    return typeof v === "function" ? v.bind(t) : v;
  },
});
use(proxy);      // the collaborator holds only the forwarder
revoke();        // the grantor holds only the revoker; later traps throw TypeError
